{
  "decision-reserve-a-weather-resilient-pick-plan": "WITH chosen AS (SELECT plan_code, MIN(sale_cartons) AS guaranteed_cartons FROM field_trial GROUP BY plan_code COLLATE BINARY HAVING MAX(bulk_bins) <= (SELECT vacant_spaces FROM cool_room) ORDER BY guaranteed_cartons DESC, plan_code COLLATE BINARY LIMIT 1) SELECT c.plan_code, c.guaranteed_cartons, t.trial_id FROM chosen AS c JOIN field_trial AS t ON t.plan_code COLLATE BINARY = c.plan_code AND t.sale_cartons = c.guaranteed_cartons ORDER BY t.trial_id COLLATE BINARY LIMIT 1",
  "decision-reserve-an-unbroken-charging-window": "SELECT a.start_min, d.initial_kwh + a.delivery_kwh + b.delivery_kwh AS final_kwh, a.price_cents + b.price_cents AS cost_cents, d.source_id FROM charger_slot AS a JOIN charger_slot AS b ON b.start_min = a.start_min + 10 CROSS JOIN duty_card AS d WHERE a.start_min >= 0 AND b.start_min + 10 <= d.pullout_min AND a.price_cents IS NOT NULL AND b.price_cents IS NOT NULL AND (d.initial_kwh + a.delivery_kwh + b.delivery_kwh) BETWEEN d.required_kwh AND d.capacity_kwh ORDER BY cost_cents, a.start_min LIMIT 1",
  "decision-reserve-folio-stock-before-demand-is-known": "SELECT m.memo_id, o.offer_id, o.lot_sheets AS staged_sheets, SUM(d.weight_pct * (o.fee_cents + m.rush_cents * MAX(d.need_sheets - o.lot_sheets, 0) - m.pulp_cents * MAX(o.lot_sheets - d.need_sheets, 0))) AS cost_hundredths_cent FROM folio_offer AS o CROSS JOIN press_memo AS m CROSS JOIN demand_outcome AS d WHERE o.lot_sheets <= m.stage_cap GROUP BY m.memo_id, o.offer_id COLLATE BINARY, o.lot_sheets, o.fee_cents ORDER BY cost_hundredths_cent, staged_sheets, o.offer_id COLLATE BINARY LIMIT 1",
  "decision-reserve-proof-press-slot": "WITH bookings(first_batch, second_batch, total_points, occupied_min) AS (SELECT batch_code, NULL, service_points, run_min FROM proof_queue UNION ALL SELECT a.batch_code, b.batch_code, a.service_points + b.service_points, a.run_min + b.run_min + CASE WHEN a.ink_code COLLATE BINARY <> b.ink_code THEN 3 ELSE 0 END FROM proof_queue AS a JOIN proof_queue AS b ON a.batch_code COLLATE BINARY < b.batch_code) SELECT first_batch, second_batch, total_points, occupied_min FROM bookings WHERE occupied_min <= 12 ORDER BY total_points DESC, occupied_min, first_batch COLLATE BINARY, second_batch COLLATE BINARY LIMIT 1"
}
